'use strict';
const KEY='stinc-os-demo-v1';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',flag:'<path d="M5 21V4m0 0c5-4 9 4 15 0v11c-6 4-10-4-15 0"/>',play:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m10 8 6 4-6 4z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',bag:'<path d="M4 7h16l1 14H3zM8 8V6a4 4 0 0 1 8 0v2"/>',money:'<rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M5 12h1m12 0h1"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-8z"/>',link:'<path d="m10 13 4-4m-6 6-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 5 0m2 2 3-3a4 4 0 0 1 5 5l-5 5a4 4 0 0 1-5 0"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',bell:'<path d="M5 16h14l-2-4V8a5 5 0 0 0-10 0v4zm5 4h4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',headphones:'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 13H2v7h5v-7zm16 0h2v7h-5v-7z"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3zm7 0 1 2 2 1-2 1-1 2-1-2-2-1 2-1z"/>'};
const ic=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=()=>({artist:'ralfy',campaigns:[{id:'c1',artist:'ralfy',name:'The next chapter',type:'Release rollout',date:'2026-11-20',goal:'Grow streams and capture first-party fans',status:'Active',progress:64},{id:'c2',artist:'ralfy',name:'From live to everywhere',type:'Livestream growth',date:'2026-11-13',goal:'Turn one livestream into a week of content',status:'Active',progress:38},{id:'c3',artist:'ralfy',name:'Built for the team',type:'Merchandise drop',date:'2026-11-27',goal:'Connect engaged fans with the official store',status:'Draft',progress:15},{id:'c4',artist:'roster',name:'Roster discovery sessions',type:'Livestream growth',date:'2026-11-21',goal:'Introduce emerging artists to new fans',status:'Draft',progress:10}],clips:[{id:'v1',artist:'ralfy',title:'The story behind the record',caption:'Every record starts with a real story. Which track takes you back?',hook:'Every record has a story.',duration:'0:32',score:94,platform:'YouTube Shorts',status:'Needs review',date:'2026-11-08',time:'18:00',source:'Studio session · sample source',start:'02:14'},{id:'v2',artist:'ralfy',title:'A moment for the day ones',caption:'Day ones know. Tap in with the team.',hook:'For the ones who stayed.',duration:'0:24',score:91,platform:'Instagram Reels',status:'Scheduled',date:'2026-11-09',time:'16:30',source:'Community live · sample source',start:'12:08'},{id:'v3',artist:'ralfy',title:'Studio to the streets',caption:'From the studio to your speakers. Follow for the next chapter.',hook:'The next chapter starts here.',duration:'0:41',score:88,platform:'TikTok',status:'Needs review',date:'2026-11-10',time:'19:00',source:'Studio session · sample source',start:'08:42'}],leads:[{id:'o1',name:'Independent streetwear partner',type:'Brands & partnerships',category:'Fashion · capsule collaboration',score:96,stage:'Qualified',value:'$8,000–$15,000',reason:'A capsule drop connects the artist’s independent identity with an audience already interested in STINC TEAM merchandise.',contact:'Decision-maker research required'},{id:'o2',name:'Creator audio partner',type:'Brands & partnerships',category:'Audio · livestream sponsorship',score:92,stage:'Qualified',value:'$4,000–$7,500',reason:'A recurring studio livestream creates natural product placement and repeat visibility for an audio brand.',contact:'Public partnerships contact required'},{id:'o3',name:'West Coast culture publication',type:'PR & press',category:'Editorial · artist profile',score:95,stage:'Qualified',value:'Earned coverage',reason:'An editorial profile can connect the artist’s independent career, creative process and community with a culturally relevant readership.',contact:'Editorial contact research required'},{id:'o4',name:'Independent music podcast',type:'PR & press',category:'Interview · release conversation',score:89,stage:'Draft ready',value:'Earned coverage',reason:'A long-form interview can support the release story and provide additional short-form content.',contact:'Producer contact research required'}],activity:[{title:'Content agent prepared 3 clip candidates',detail:'Studio session → short-form review queue',at:'12 minutes ago'},{title:'Partnership agent ranked 2 brand opportunities',detail:'Fit scores and pitch angles ready for review',at:'38 minutes ago'},{title:'Campaign agent mapped the next release',detail:'Content, fan capture and merchandise milestones',at:'1 hour ago'}],paused:[],settings:{weekly:true,review:true},pitches:{}});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed();if(!Array.isArray(state.campaigns)||!Array.isArray(state.clips)||!state.settings)state=seed()}catch{state=seed()}
let live=null;
let page=location.hash.slice(1)||'overview',filter='All',opTab='Brands & partnerships',period='30',toastTimer,lastFocus,pendingCampaign;
state.leads.forEach(x=>{if(!x.artist)x.artist='ralfy'});state.fanPages=state.fanPages||{};if(state.fanPage){state.fanPages.ralfy=state.fanPage;delete state.fanPage}
const artistName=()=>state.artist==='ralfy'?'Ralfy the Plug':'Emerging artist · demo';
const own=(arr)=>arr.filter(x=>x.artist===state.artist);
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage is unavailable. Export your workspace to keep changes.')}};
function log(title,detail){state.activity.unshift({title,detail,at:'Just now'});state.activity=state.activity.slice(0,25);save()}
const navs=[['overview','grid','Overview'],['operations','spark','What’s running'],['content','play','Content studio'],['calendar','calendar','Calendar'],['opportunities','target','Opportunities'],['fans','people','Fans & community'],['commerce','bag','Commerce'],['revenue','money','Revenue']];
function shell(){document.getElementById('app').innerHTML=`<aside class="sidebar" id="sidebar"><button class="icon-btn mobile-close" data-action="menu" aria-label="Close navigation">${ic('close')}</button><a class="logo" href="#overview"><img src="assets/mark.svg" alt=""><span>STINC <span>OS</span></span></a><div class="label-tag"><strong>STINC TEAM ${ic('chevron')}</strong><small>Label workspace</small></div><div class="nav-title">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${navs.map(([id,icon,name])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${ic(icon)}${name}${id==='opportunities'?`<span class="count">${liveForRalfy()&&live.sponsors?live.sponsors.tracked:own(state.leads).length}</span>`:''}</a>`).join('')}</nav><div class="nav-divider"></div><div class="nav"><a href="#roster" class="${page==='roster'?'active':''}">${ic('people')}Artist roster</a><a href="#agents" class="${page==='agents'?'active':''}">${ic('spark')}Agent workforce</a><a href="#integrations" class="${page==='integrations'?'active':''}">${ic('link')}Connections</a></div><div class="sidebar-bottom"><div class="agent-mini"><span class="dot"></span><strong class="small">Your team, in motion</strong><p class="muted small" style="margin-top:5px">${liveForRalfy()&&live.ops?(live.ops.processes||[]).length+' processes running for Ralfy':'Run by our team'}</p><a href="#operations" class="btn subtle small">See what’s running ${ic('arrow')}</a></div><div class="user"><div class="avatar">EV</div><div><strong>EVOL</strong><small>Label manager · Demo persona</small></div></div></div></aside><button class="nav-scrim" data-action="menu" aria-label="Close navigation overlay" tabindex="-1"></button><div class="shell"><header class="topbar"><div class="breadcrumbs"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle navigation" aria-controls="sidebar" aria-expanded="false">${ic('menu')}</button><span class="crumb-label">Workspace</span><span class="crumb-label">/</span><strong>${esc(artistName())}</strong></div><div class="top-right"><span class="badge"><span class="dot"></span>${live?'Live snapshot':'Demo workspace'}</span><select class="artist-select" id="artist-select" aria-label="Select artist"><option value="ralfy" ${state.artist==='ralfy'?'selected':''}>Ralfy the Plug</option><option value="roster" ${state.artist==='roster'?'selected':''}>Emerging artist · demo</option></select><button class="icon-btn" data-action="notifications" aria-label="Activity notifications">${ic('bell')}</button></div></header><main class="main skeleton" id="main" tabindex="-1">${renderPage()}</main></div>`;bind();}
const button=(label,action,primary=false,icon='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}">${icon?ic(icon):''}${label}</button>`;
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
const footer=()=>`<footer class="footer"><span>STINC OS / Independent ambition. Connected execution.</span><button data-action="about">${live?'Public snapshot · Sample figures labeled':'Concept demo · Sample data · No accounts connected'} ${ic('arrow')}</button></footer>`;
function metrics(items){return `<div class="metrics">${items.map(([label,num,trend,icon,kind])=>{const asof=kind==='asof';const badge=kind==='sample'?sampleMark:'';return `<div class="metric"><div class="metric-label">${ic(icon||'grid')}${esc(label)} ${badge}</div><div class="number">${esc(num)}</div><div class="trend">${esc(trend)}</div></div>`}).join('')}</div>`}
function chart(){return `<div class="chart"><svg viewBox="0 0 530 156" role="img" aria-label="Sample content views trend upward during the selected period"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#c5f277" stop-opacity=".16"/><stop offset="1" stop-color="#c5f277" stop-opacity="0"/></linearGradient></defs>${[20,60,100,140].map((y,i)=>`<path d="M35 ${y}H525" stroke="#30362e" stroke-dasharray="3 5"/><text x="0" y="${y+4}" fill="#7c8873" font-size="9">${[60,40,20,0][i]}k</text>`).join('')}<path d="M35 125 60 119 85 124 110 106 135 113 160 97 185 105 210 80 235 85 260 68 285 82 310 59 335 66 360 43 385 54 410 32 435 45 460 20 485 28 525 9V145H35Z" fill="url(#area)"/><path d="M35 125 60 119 85 124 110 106 135 113 160 97 185 105 210 80 235 85 260 68 285 82 310 59 335 66 360 43 385 54 410 32 435 45 460 20 485 28 525 9" fill="none" stroke="#c5f277" stroke-width="2" stroke-linejoin="round"/><path d="M35 137 70 133 105 137 140 123 175 128 210 115 245 124 280 108 315 119 350 103 385 111 420 93 455 105 490 88 525 94" fill="none" stroke="#799eae" stroke-width="1.5"/></svg><div class="chart-labels">${(period==='7'?['Nov 1','Nov 2','Nov 3','Nov 4','Nov 5','Nov 7']:['Oct 9','Oct 15','Oct 21','Oct 27','Nov 2','Nov 7']).map(t=>`<span>${t}</span>`).join('')}</div></div>`}
const sampleMark='<span class="badge gray">Sample</span>';
function liveForRalfy(){return !!(live&&live.schema==='stinc-os.live.v1'&&state.artist==='ralfy')}
function fmtDur(seconds){const s=Number(seconds);if(!isFinite(s)||s<=0)return '';const total=Math.round(s);return Math.floor(total/60)+':'+String(total%60).padStart(2,'0')}
function money(n){const x=Number(n);if(!isFinite(x))return '';return '$'+(Math.round(x)===x?x.toFixed(0):x.toFixed(2))}
function metricRows(rows){return rows.map(row=>[row.label,row.value,row.as_of||'Public snapshot',row.icon||'grid','asof'])}
function momentumBlock(alt){const real=liveForRalfy()&&Array.isArray(live.highlights)&&live.highlights.length?live.highlights:null;const rows=real?metricRows(real):(alt?[['Content views','42.8K','12.4%','play','sample'],['Music streams','18.2K','9.2%','headphones','sample'],['Owned fans','284','8.1%','people','sample'],['Attributed sales','$840','11.3%','bag','sample']]:period==='7'?[['Content views','324.8K','21.6%','play','sample'],['Music streams','84.2K','10.4%','headphones','sample'],['Owned fans','1,862','4.2%','people','sample'],['Attributed sales','$3,420','18.1%','bag','sample']]:[['Content views','1.28M','24.8%','play','sample'],['Music streams','342.8K','18.2%','headphones','sample'],['Owned fans','1,862','12.6%','people','sample'],['Attributed sales','$12,480','32.4%','bag','sample']]);const pipeline=real&&Array.isArray(live.pipeline_highlights)&&live.pipeline_highlights.length?metrics(metricRows(live.pipeline_highlights)):'';return `<div class="split" style="margin-bottom:10px"><span class="eyebrow muted">${real?'MOMENTUM / PUBLIC SNAPSHOT':'MOMENTUM / SAMPLE PERFORMANCE'} ${real?'<span class="badge">Live</span>':sampleMark}</span><select class="artist-select" id="period" aria-label="Performance date range"><option value="30" ${period==='30'?'selected':''}>Last 30 days</option><option value="7" ${period==='7'?'selected':''}>Last 7 days</option></select></div>`+metrics(rows)+pipeline}
function fmtWhen(row){return esc((row&&row.scheduled_label)||(row&&row.at_label)||(row&&row.at)||'')}
function scoreBars(b){if(!b)return '';const rows=[['Story','story'],['Hook','hook'],['Audio','audio'],['Chat hype','chat_hype'],['Traction','traction']];return `<div class="score-break">${rows.map(([label,key])=>{const v=b[key];const has=typeof v==='number'&&isFinite(v);const fallback=(key==='traction'&&b.traction_label)?b.traction_label:'—';const pct=has?Math.max(0,Math.min(100,(v/10)*100)):0;return `<div class="score-row"><span>${esc(label)}</span><span class="score-track">${has?`<i style="width:${pct}%"></i>`:''}</span><b>${has?esc(v):esc(fallback)}</b></div>`}).join('')}</div>`}
function pipelinePanel(){if(!liveForRalfy()||!live.pipeline)return '';const p=live.pipeline,f=live.fans||{};const mix=p.mix||f.mix||'';return `<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Content pipeline <span class="badge">Live</span></h2><p>${esc(mix||'Stream clips and music-video teasers scored for the fan pages.')}</p></div></div>`+metrics([['Streams scanned',String(p.streams_scanned||p.source_videos||0),'Public VODs','play','asof'],['Music videos scanned',String(p.music_videos_scanned||0),'Official public videos','headphones','asof'],['Moments found',String(p.clip_options||0),'Scored candidates','spark','asof'],['Clips rendered',String(p.clips_rendered||0),'Vertical files','play','asof']])+`</section>`}
function upcomingPanel(){if(!liveForRalfy()||!Array.isArray(live.queue)||!live.queue.length)return '';return `<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Upcoming fan-page posts <span class="badge">Live</span></h2><p>Scheduled times are America/New_York. Official accounts are not used.</p></div></div><div class="table-wrap"><table class="queue-table"><thead><tr><th>When</th><th>Channel</th><th>Type</th><th>Clip</th></tr></thead><tbody>${live.queue.map(row=>`<tr><td>${fmtWhen(row)}</td><td>${esc(row.platform||'')}</td><td><span class="badge ${row.kind==='music'?'purple':''}">${esc(row.kind==='music'?'Music':'Stream')}</span></td><td>${esc(row.title||'')}</td></tr>`).join('')}</tbody></table></div></section>`}
function activityPanel(limit){if(!liveForRalfy()||!Array.isArray(live.activity)||!live.activity.length)return '';const rows=live.activity.slice(0,limit||8);return `<section class="panel"><div class="panel-head"><div><h2>Activity <span class="badge">Live</span></h2><p>Automated actions from the latest snapshot.</p></div></div>${rows.map(a=>`<div class="activity"><span class="activity-dot"></span><div><b>${esc(a.label||'Update')}</b><p>${esc(a.detail||'')} · ${fmtWhen(a)}</p></div></div>`).join('')}</section>`}
function topBreakdown(){if(!liveForRalfy()||!Array.isArray(live.clips)||!live.clips.length)return '';const top=live.clips.find(c=>c.breakdown)||live.clips[0];if(!top||!top.breakdown)return '';return `<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Top clip score <span class="badge">Live</span></h2><p>${esc(top.title||top.hook||'Top scored moment')} · ${top.viral==null?'':esc(top.viral)+' viral'}</p></div></div><div class="split score-hero">${top.thumb?`<img class="thumb-frame" src="${esc(top.thumb)}" alt="">`:`<div class="clip-art compact"><img src="assets/ralfy.png" alt=""></div>`}<div>${scoreBars(top.breakdown)}${top.breakdown.traction_label&&top.breakdown.traction!=null?`<p class="muted small" style="margin-top:10px">${esc(top.breakdown.traction_label)}</p>`:''}</div></div></section>`}
function campaignAggregate(){if(!liveForRalfy()||!live.sponsors||!live.pipeline)return '';const s=live.sponsors,p=live.pipeline,f=live.fans||{};const posted=f.posts_published_total||p.posted||0;const cadence=f.warmup||'2/day per live channel';return metrics([['Sponsors sent',String(s.sent),`Queued ${s.queued} · email cap ${s.email_daily_cap||s.daily_cap}/day`,'target','asof'],['Forms in pipeline',String(s.forms_queued||0),`Submitted ${s.forms_submitted||0} · cap ${s.forms_daily_cap||10}/day`,'flag','asof'],['Clip options',String(p.clip_options),p.mix||'Fan-page mix','play','asof'],['Posts published',String(posted),cadence,'calendar','asof']])}
function liveClipRows(){if(!liveForRalfy()||!Array.isArray(live.clips))return [];return live.clips.filter(c=>filter==='All'||c.status===filter)}
function liveContentSection(){const rows=liveClipRows();if(!liveForRalfy())return '';return pipelinePanel()+upcomingPanel()+topBreakdown()+(rows.length?`<div class="split" style="margin-bottom:10px"><span class="eyebrow muted">LIVE CANDIDATES <span class="badge">Live</span></span><span class="muted small">Viral scores from the content engine. Posted only to fan pages we control.</span></div><div class="content-grid" style="margin-bottom:22px">${rows.map(c=>`<article class="panel clip"><div class="clip-art"><img src="${esc(c.thumb||'assets/ralfy.png')}" alt="${esc(c.title)}"><div class="play">${ic('play')}</div><div class="caption">${esc(c.hook||c.title)}</div>${fmtDur(c.duration_s)?`<span class="duration">${esc(fmtDur(c.duration_s))}</span>`:''}</div><div class="split"><span class="badge ${c.status==='Needs review'?'yellow':''}">${esc(c.status)}</span><span class="small green">${c.viral==null?'':esc(c.viral)+' viral'}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.source_label||'Public source')}${fmtDur(c.duration_s)?` · ${esc(fmtDur(c.duration_s))}`:''}</p><div class="split"><span class="muted small">${esc(c.kind==='music'?'Music video':'Stream VOD')}</span>${c.watch_url?`<a class="btn" href="${esc(c.watch_url)}" target="_blank" rel="noopener noreferrer">Watch source ${ic('arrow')}</a>`:''}</div></article>`).join('')}</div>`:'')}
function sponsorPanel(){if(!liveForRalfy()||!live.sponsors)return '';const s=live.sponsors;const channels=Array.isArray(s.by_channel)?s.by_channel:[];const email=channels.find(c=>c.channel==='email')||{};const form=channels.find(c=>c.channel==='form')||{};return `<div class="note">Sponsor outreach is counts only <span class="badge">Live</span>. Brand names, contacts, and deal terms stay off this public site. Legal-hold rows are omitted.</div>`+metrics([['Emails sent',String(s.sent),`Cap ${s.email_daily_cap||s.daily_cap} a weekday`,'target','asof'],['Emails queued',String(s.queued),'Aggregate','flag','asof'],['Replies',String(s.replies),'Aggregate','people','asof'],['Forms queued',String(s.forms_queued||form.queued||0),`Submitted ${s.forms_submitted||form.submitted||0} · cap ${s.forms_daily_cap||form.daily_cap||10}/day, ${s.forms_min_spacing_min||form.min_spacing_min||30}+ min spacing`,'grid','asof']])+(channels.length?`<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>By channel <span class="badge">Live</span></h2><p>Aggregates only — no brand names.</p></div></div>${channels.map(c=>`<div class="segment"><div class="task-icon">${ic(c.channel==='form'?'flag':'target')}</div><div><h3>${esc(c.channel==='form'?'Form applications':'Email outreach')}</h3><p>${c.channel==='form'?`Queued ${c.queued||0} · submitted ${c.submitted||0} · ${c.submitted_today||0} today`:`Sent ${c.sent||0} · queued ${c.queued||0} · ${c.replies||0} replies`}</p></div><span class="number">${esc(c.channel==='form'?(c.queued||0):(c.sent||0))}</span></div>`).join('')}</section>`:'')}
function fanPanel(){if(!liveForRalfy()||!live.fans||!Array.isArray(live.fans.accounts))return '';const f=live.fans,accounts=f.accounts,official=Array.isArray(f.official)?f.official:[];const warmup=f.warmup||'2 posts per day per live channel, 30-minute stagger';return `<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Fan-page network <span class="badge">Live</span></h2><p>${esc(f.name||'Ralfy Clips')} · autopilot ${esc(f.posting||'off')}${f.mix?` · ${esc(f.mix)}`:''}</p></div></div>`+metrics([['Channels live',`${f.channels_live||0}/${f.channels_total||accounts.length||0}`,warmup,'people','asof'],['Posts published',String(f.posts_published_total||0),`${f.posts_scheduled_total||0} scheduled ahead`,'calendar','asof']])+accounts.map(a=>{const slots=(a.slot_times_et||[]).join(' / ');const counts=[a.posts_published!=null?`${a.posts_published} published`:'',a.posts_scheduled!=null?`${a.posts_scheduled} scheduled`:'',a.per_day?`${a.per_day}/day`:'',slots?`${slots} ET`:''].filter(Boolean).join(' · ');const coming=/coming soon/i.test(a.status||'')||!a.url;return `<div class="settings-row"><div class="connection-logo">${esc(String(a.platform||'?').slice(0,1))}</div><div class="info"><h3>${esc(a.handle||a.platform)}</h3><p>${esc(a.platform||'')}${a.status?` · ${esc(a.status)}`:''}${counts?` · ${esc(counts)}`:''}${a.followers?` · ${esc(a.followers)} followers`:''}</p></div>${a.url?`<a class="btn" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">Open ${ic('arrow')}</a>`:`<span class="badge gray">${coming?'Coming soon':'No public URL yet'}</span>`}</div>`}).join('')+`<div class="note">Warm-up: ${esc(warmup)}. Official artist accounts stay untouched.</div></section>`+(official.length?`<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Official artist accounts <span class="badge">Live</span></h2><p>Public figures, for context. This workspace does not post here.</p></div></div>${official.map(a=>`<div class="settings-row"><div class="connection-logo">${esc(String(a.platform||'?').slice(0,1))}</div><div class="info"><h3>${esc(a.handle||a.platform)}</h3><p>${esc(a.platform||'')}${a.status?` · ${esc(a.status)}`:''}</p></div>${a.url?`<a class="btn" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">Open ${ic('arrow')}</a>`:''}</div>`).join('')}</section>`:'')}
function commerceMetrics(){if(liveForRalfy()&&live.commerce){const c=live.commerce;return metrics([['Store products',String(c.store_published_count??'—'),`As of ${c.as_of||'snapshot'}`,'bag','asof'],['In stock',String(c.store_in_stock_count??'—'),'Public store','grid','asof'],['Listed here',String(c.shown_count??'—'),'Public subset','bag','asof'],['Email drafts',String(c.emails_built??(c.emails||[]).length),'Not sending','link','asof']])}return metrics([['Sample sales','$12,480','32.4%','bag','sample'],['Sample orders','208','21.2%','grid','sample'],['Average order','$60.00','9.2%','money','sample'],['Store conversion','3.4%','0.8 pts','target','sample']])}
function commerceNote(){if(liveForRalfy()&&live.commerce)return `<div class="note">Checkout and orders stay on the public store <span class="badge">Live</span>. The list below is a sanitized catalog snapshot. Some store items are not listed here.</div>`;return `<div class="note">${sampleMark} Store metrics are illustrative. Product sales, inventory and checkout remain in Shopify. A conversational storefront designer is part of the future product roadmap.</div>`}
function commerceExtra(){if(!liveForRalfy()||!live.commerce)return '';const c=live.commerce;const products=(c.products||[]).map(p=>`<tr><td>${esc(p.title)}<small>${esc(p.category||'')}${p.instock_sizes&&p.instock_sizes.length?' · '+esc(p.instock_sizes.join(', ')):''}</small></td><td>${esc(money(p.price_min))}</td><td><span class="badge ${p.available?'':'gray'}">${p.available?'In stock':'Sold out'}</span></td><td><a class="btn" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">View ${ic('arrow')}</a></td></tr>`).join('');const emails=(c.emails||[]).map(e=>`<article class="panel campaign-card"><span class="badge">Draft</span><h2>${esc(e.subject)}</h2><p>${esc(e.series||'')} · ${esc(e.segment||'')}</p>${e.preheader?`<p class="muted small">${esc(e.preheader)}</p>`:''}</article>`).join('');return `<section class="panel"><div class="panel-head"><div><h2>Public rack <span class="badge">Live</span></h2><p>${esc(String(c.shown_count||0))} shown of ${esc(String(c.store_published_count||''))} on the store</p></div><a class="btn" href="${esc(c.store_url||'https://stincteamtgf.com/')}" target="_blank" rel="noopener noreferrer">Official store ${ic('arrow')}</a></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th></th></tr></thead><tbody>${products}</tbody></table></div></section><br><div class="note">${esc(c.previews_reason||'Email drafts are not sending.')}</div><div class="cards">${emails}</div>`}
const CONNECTORS=[{id:'spotify',name:'Spotify for Artists',mark:'S',group:'Streaming',state:'soon',blurb:'Streaming analytics for the artist profile.',detail:'Spotify for Artists has no public API. This stays on manual import. The public Spotify Web API can read a public artist profile only, and this page does not call it.'},{id:'apple',name:'Apple Music',mark:'A',group:'Streaming',state:'soon',blurb:'Catalog and analytics.',detail:'Apple Music analytics are not a free public API. Manual import later. Nothing is connected.'},{id:'ytmusic',name:'YouTube Music',mark:'Y',group:'Streaming',state:'off',blurb:'YouTube channel and music catalog.',detail:'We connect YouTube with channel-manager access. Nothing is connected yet.'},{id:'shopify',name:'Shopify',mark:'S',group:'Commerce',state:'off',blurb:'Products, orders, and conversion.',detail:'We connect Shopify with collaborator or staff access. Catalog facts on this page come from the public store.'},{id:'website',name:'Your website or merch store',mark:'W',group:'Commerce',state:'manual',blurb:'A store URL you already run.',detail:'The official store link. Orders stay on the store.'},{id:'instagram',name:'Instagram',mark:'I',group:'Social',state:'off',blurb:'Professional account analytics.',detail:'We connect Instagram insights with professional-account access. Nothing is connected yet.'},{id:'tiktok',name:'TikTok',mark:'T',group:'Social',state:'soon',blurb:'Video analytics and publishing.',detail:'TikTok’s API needs app review and is not an open free connector. Manual import later. Nothing is connected.'},{id:'youtube',name:'YouTube',mark:'Y',group:'Social',state:'off',blurb:'Channel analytics and public videos.',detail:'We connect YouTube analytics with channel access. Public video links on this site are not a channel login.'},{id:'x',name:'X',mark:'X',group:'Social',state:'soon',blurb:'Public posts and audience.',detail:'X does not offer this workspace a free analytics API. Manual import later. Nothing is posted.'},{id:'clipping',name:'Clipping channels',mark:'C',group:'Clipping',state:'local',blurb:'Content engine candidates and viral scores.',detail:'Clipping runs on our content engine. This site shows a public snapshot.'}];
function connectorBadge(c){if(c.id==='clipping'){const on=liveForRalfy()&&live.pipeline&&live.pipeline.clip_options>0;return on?'<span class="badge">Running</span>':'<span class="badge gray">Not connected</span>'}if(c.state==='soon')return '<span class="badge yellow">Coming soon</span>';if(c.state==='manual')return '<span class="badge gray">Manual import</span>';return '<span class="badge gray">Not connected</span>'}
function connectModal(id){const c=CONNECTORS.find(x=>x.id===id);if(!c)return;const store=c.id==='website'?`<form id="store-form"><label class="field">Public store URL<input id="store-url" name="url" type="url" value="${esc(state.storeUrl||'')}" placeholder="https://"></label><div class="modal-footer">${button('Cancel','close')}<button class="btn primary" type="submit">Save in this browser</button></div></form>`:'';modal(esc(c.name),`<p>${esc(c.detail)}</p>${c.state==='off'?'<div class="note">Not connected yet. We set this up with admin or collaborator access.</div>':''}${c.state==='soon'?'<div class="note">Coming soon / manual import. There is no free public API for this connector.</div>':''}${store}<div class="modal-footer">${store?'':button('Understood','close',true)}</div>`);if(store)document.getElementById('store-form').addEventListener('submit',e=>{e.preventDefault();action('save-store')})}

function tabs(list){return `<div class="tabs" role="group" aria-label="Filter results">${list.map(t=>`<button class="tab ${filter===t?'active':''}" data-filter="${esc(t)}" aria-pressed="${filter===t}">${t}</button>`).join('')}</div>`}
const agents=[['campaign','Campaign strategist','Turns an artist goal into a coordinated release, content and fan-growth plan.','flag'],['content','Content producer','Organizes clip candidates, captions and the publishing queue.','play'],['partnership','Opportunity scout','Ranks commercial and editorial opportunities with a visible reason for fit.','target'],['community','Community operator','Plans fan capture and relevant follow-up around releases and drops.','people']];
const liveTag='<span class="badge">Live</span>';
const plannedTag='<span class="badge purple">Planned</span>';
const OPS=()=>liveForRalfy()&&live.ops?live.ops:null;
const extLink=(url,label)=>url?`<a class="btn" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ${ic('arrow')}</a>`:'';
const chanName=(p)=>({instagram:'Instagram',tiktok:'TikTok',x:'X',youtube:'YouTube Shorts'}[String(p||'').toLowerCase()]||p||'');
const kindTag=(k)=>`<span class="badge ${k==='music'?'purple':''}">${k==='music'?'Music':'Stream'}</span>`;
const snapLabel=()=>{if(!live||!live.generated_at)return '';const d=new Date(live.generated_at);if(isNaN(d))return '';return d.toLocaleString('en-US',{timeZone:'America/New_York',weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' ET'};
const refreshNote=()=>`<div class="note">${liveTag} Read-only view of the work we run for Ralfy.${snapLabel()?` Updated ${esc(snapLabel())}.`:''} Refreshes at 9 AM, 2 PM and 9 PM ET.</div>`;
const CONNECT_NEEDS=[['Distributor','DistroKid, TuneCore, AWAL or similar: read access, or monthly statements'],['DSP artist dashboards','Spotify for Artists, Apple Music for Artists, YouTube Studio and Content ID'],['Performing rights (PRO)','BMI or ASCAP writer and publisher statements'],['Publishing admin and The MLC','Mechanical royalties and song registrations'],['SoundExchange','Digital performance royalties'],['Shopify','Orders, customers and inventory for merch'],['Google Analytics','Traffic to the official site'],['Link-in-bio','Linktree or similar: clicks from social'],['Email / SMS platform','The fan list, so we can reach fans on release and drop days'],['Ticketing','Eventbrite or similar, for shows and events']];
function needsPanel(title,sub){return `<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>${title}</h2><p>${sub}</p></div>${plannedTag}</div>${CONNECT_NEEDS.map(([n,d],i)=>`<div class="settings-row"><div class="connection-logo">${String(i+1).padStart(2,'0')}</div><div class="info"><h3>${esc(n)}</h3><p>${esc(d)}</p></div><span class="badge gray">Not connected</span></div>`).join('')}<div class="note" style="margin:16px 0 0">We ask for admin or collaborator access on each account, never a password. Read access is enough for revenue and analytics.</div></section>`}
function engineKpis(){if(!liveForRalfy())return '';const p=live.pipeline||{},f=live.fans||{},s=live.sponsors||{};return `<div class="split" style="margin-bottom:10px"><span class="eyebrow muted">WHAT WE HAVE RUN SO FAR ${liveTag}</span><span class="muted small">Running totals</span></div>`+metrics([['Fan-page channels live',`${f.channels_live||0}/${f.channels_total||0}`,'Instagram and TikTok live · X and YouTube next','people','asof'],['Posts published',String(f.posts_published_total||0),'On the fan pages','play','asof'],['Posts scheduled',String(f.posts_scheduled_total||0),'2 a day per live channel','calendar','asof'],['Clips rendered',String(p.clips_rendered||0),`${p.clip_options||0} moments scored`,'spark','asof']])+metrics([['Moments scored',String(p.clip_options||0),`From ${p.streams_scanned||0} streams and ${p.music_videos_scanned||0} music video`,'target','asof'],['Brand emails sent',String(s.sent||0),`Running total · up to ${s.email_daily_cap||3} a weekday`,'target','asof'],['Brand forms submitted',String(s.forms_submitted||0),`${s.forms_queued||0} waiting · up to ${s.forms_daily_cap||10} a day`,'flag','asof'],['Merch emails designed',String((live.commerce&&live.commerce.emails_built)||p.emails_built||0),'Ready once the fan list is connected','link','asof']])}
function officialKpis(){if(!liveForRalfy()||!Array.isArray(live.highlights)||!live.highlights.length)return '';return `<div class="split" style="margin-bottom:10px"><span class="eyebrow muted">RALFY’S OFFICIAL ACCOUNTS ${liveTag}</span><span class="muted small">Public figures, with their date</span></div>`+metrics(metricRows(live.highlights))}
function todayPanel(compact){const o=OPS();if(!o||!o.today)return '';const t=o.today,chans=t.channels||[];const rows=chans.map(c=>`<tr><td>${esc(c.channel)}</td><td>${c.live?esc(c.planned):'—'}</td><td>${c.live?esc(c.published):'—'}</td><td>${c.live?esc(c.due):'—'}</td><td>${c.live?esc(c.upcoming):'—'}</td><td>${c.live?(c.published+c.due>=c.planned&&c.planned?'<span class="badge">On track</span>':'<span class="badge">Running</span>'):plannedTag}</td></tr>`).join('');const items=compact?'':chans.filter(c=>c.live).flatMap(c=>(c.items||[]).map(i=>({...i,channel:c.channel,profile:c.profile_url}))).sort((a,b)=>String(a.at).localeCompare(String(b.at))).map(i=>`<div class="settings-row"><div class="connection-logo">${esc(i.channel.slice(0,1))}</div><div class="info"><h3>${esc(i.time)} · ${esc(i.channel)} ${kindTag(i.kind)}</h3><p>${esc(i.title)}</p></div>${i.state==='published'?`<span class="badge">Published</span>${extLink(i.url,'View post')}`:i.state==='due'?`<span class="badge yellow">Handed to scheduler · link pending</span>${extLink(i.profile,'Channel')}`:`<span class="badge gray">Scheduled</span>${extLink(i.profile,'Channel')}`}</div>`).join('');return `<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Today: planned vs executed ${liveTag}</h2><p>${esc(t.date||'Today')} · fan-page posts by channel · times ET</p></div></div><div class="table-wrap"><table class="queue-table"><thead><tr><th>Channel</th><th>Planned</th><th>Published</th><th>Handed to scheduler</th><th>Later today</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table></div>${items}<p class="muted small" style="margin-top:12px">“Handed to scheduler” means the post is due and was queued ahead of time. Its live link shows here once the next check confirms it.</p></section>`}
function outreachToday(){const o=OPS();if(!o||!o.outreach_today)return '';const x=o.outreach_today;return [['Brand emails today',`${x.emails_sent_today}/${x.emails_due_today}`,`Sent vs due · up to ${x.email_daily_cap} a weekday`,'target'],['Brand forms today',`${x.forms_submitted_today}/${x.forms_daily_cap}`,`Submitted vs daily cap · ${x.forms_queued} waiting`,'flag'],['Emails sent, all time',String(x.emails_sent_total),'Running total','link'],['Forms submitted, all time',String(x.forms_submitted),'Running total','grid']].map(([n,v,d,i])=>`<div class="segment"><div class="task-icon">${ic(i)}</div><div><h3>${n}</h3><p>${d}</p></div><span class="number">${esc(v)}</span></div>`).join('')}
function comingNext(){if(!liveForRalfy()||!Array.isArray(live.queue))return '';const now=Date.now();const rows=live.queue.filter(r=>!r.scheduled_at||Date.parse(r.scheduled_at)>now).slice(0,6);const procs=(OPS()&&OPS().processes||[]).filter(p=>p.next_run).slice(0,4);return `<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Coming next ${liveTag}</h2><p>Next posts and the next scheduled runs.</p></div></div>${rows.map(r=>`<div class="activity"><span class="activity-dot"></span><div><b>${fmtWhen(r)} · ${esc(chanName(r.platform))}</b><p>${esc(r.kind==='music'?'Music':'Stream')} clip · ${esc(r.title||'')}</p></div></div>`).join('')}${procs.map(p=>`<div class="activity"><span class="activity-dot"></span><div><b>${esc(p.next_run)} · ${esc(p.name)}</b><p>${esc(p.cadence)}</p></div></div>`).join('')}</section>`}
function operations(){if(!liveForRalfy())return heading('What’s running','Everything our team and agents run for this artist.')+`<div class="note">${sampleMark} Demo roster slot. Operations show here once we onboard the artist.</div>`+footer();const o=OPS();const p=live.pipeline||{};return heading('What’s running','Everything our team and agents are doing for Ralfy today.')+refreshNote()+metrics([['Posts today',o&&o.today?`${(o.today.channels||[]).reduce((a,c)=>a+c.published+c.due,0)}/${(o.today.channels||[]).reduce((a,c)=>a+c.planned,0)}`:'—','Executed vs planned','play','asof'],['Brand emails today',o?`${o.outreach_today.emails_sent_today}/${o.outreach_today.emails_due_today}`:'—','Sent vs due','target','asof'],['Brand forms today',o?`${o.outreach_today.forms_submitted_today}/${o.outreach_today.forms_daily_cap}`:'—','Submitted vs daily cap','flag','asof'],['Clips rendered',String(p.clips_rendered||0),`${(live.fans&&live.fans.posts_published_total)||0} posted so far`,'spark','asof']])+todayPanel(false)+`<div class="grid-main"><div>${comingNext()}</div><section class="panel"><div class="panel-head"><div><h2>Outreach today ${liveTag}</h2><p>Counts only. Brand names stay private.</p></div></div>${outreachToday()}<a class="btn subtle" href="#opportunities">See the pipeline ${ic('arrow')}</a></section></div>`+activityPanel(6)+footer()}
function overview(){const alt=!liveForRalfy();const hero=`<section class="hero"><div class="hero-copy"><div class="eyebrow green">WE RUN IT. YOU SEE IT GROW.</div><h2>Independent moves.<br>Major-label execution.</h2><p>Our team and agents run the clips, the fan pages, brand outreach and the store emails. This workspace shows that work as it happens.</p><a class="btn primary" href="#operations">${ic('spark')}See what’s running</a></div>${alt?'<div class="hero-image" style="display:grid;place-items:center"><span style="font-family:Space Grotesk;font-size:100px;color:#c5f27733">EA</span></div><div class="hero-label">DEMO ROSTER SLOT<b>EMERGING ARTIST</b></div>':'<div class="hero-image"><img src="assets/ralfy.png" alt="Ralfy the Plug, from the official STINC TEAM artist profile"></div><div class="hero-label">ARTIST SPOTLIGHT<b>RALFY THE PLUG</b></div>'}</section>`;if(alt)return heading('Overview',`${artistName()}`)+hero+`<div class="note">${sampleMark} Demo roster slot. We onboard each new artist; figures below are samples until then.</div>`+metrics([['Content views','42.8K','Sample','play','sample'],['Music streams','18.2K','Sample','headphones','sample'],['Owned fans','284','Sample','people','sample'],['Store sales','$840','Sample','bag','sample']])+footer();return heading('Ralfy the Plug, this week.','What we are running for Ralfy, and what goes out next.')+hero+engineKpis()+officialKpis()+todayPanel(true)+`<div class="bottom-grid">${comingNext()}<section class="panel"><div class="panel-head"><h2>Behind the scenes ${liveTag}</h2><a href="#agents" class="btn subtle">Agent workforce ${ic('arrow')}</a></div>${(live.activity||[]).slice(0,5).map(a=>`<div class="activity"><span class="activity-dot"></span><div><b>${esc(a.label)}</b><p>${esc(a.detail||'')} · ${fmtWhen(a)}</p></div></div>`).join('')}</section></div>`+footer()}
function postLinkFor(row){const pub=(live&&live.published)||[];const m=pub.find(p=>p.platform===row.platform&&p.title===row.title);if(m)return extLink(m.url,'View post');const acc=((live&&live.fans&&live.fans.accounts)||[]).find(a=>a.platform===chanName(row.platform));return acc&&acc.url?extLink(acc.url,'Channel'):''}
function queueTable(){if(!liveForRalfy()||!Array.isArray(live.queue)||!live.queue.length)return '';return `<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Upcoming fan-page posts ${liveTag}</h2><p>Times ET. Fan pages only; Ralfy’s official accounts are never used.</p></div></div><div class="table-wrap"><table class="queue-table"><thead><tr><th>When</th><th>Channel</th><th>Type</th><th>Clip</th><th>Link</th></tr></thead><tbody>${live.queue.map(row=>`<tr><td>${fmtWhen(row)}</td><td>${esc(chanName(row.platform))}</td><td>${kindTag(row.kind)}</td><td>${esc(row.title||'')}</td><td>${postLinkFor(row)}</td></tr>`).join('')}</tbody></table></div><p class="muted small" style="margin-top:12px">Scheduled posts link to the channel until they publish; published posts link to the post itself.</p></section>`}
function publishedTable(){const rows=(liveForRalfy()&&live.published)||[];if(!rows.length)return '';return `<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Published ${liveTag}</h2><p>Real posts on the fan pages.</p></div></div><div class="table-wrap"><table class="queue-table"><thead><tr><th>Posted</th><th>Channel</th><th>Type</th><th>Clip</th><th>Link</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.at_label)}</td><td>${esc(chanName(r.platform))}</td><td>${kindTag(r.kind)}</td><td>${esc(r.title)}</td><td>${extLink(r.url,'View post')}</td></tr>`).join('')}</tbody></table></div></section>`}
function scoreCard(){if(!liveForRalfy()||!Array.isArray(live.clips)||!live.clips.length)return '';const top=live.clips.find(c=>c.breakdown)||null;if(!top)return '';return `<section class="panel score-card" style="margin-bottom:22px"><div class="panel-head"><div><h2>Top clip score ${liveTag}</h2><p>${esc(top.title||top.hook||'Top scored moment')}${top.viral==null?'':` · ${esc(top.viral)} / 10 overall`}</p></div></div><div class="score-layout">${top.thumb?`<img class="score-thumb" src="${esc(top.thumb)}" alt="">`:''}<div class="score-body">${scoreBars({...top.breakdown,traction_label:''})}<p class="muted small" style="margin-top:12px">Each moment is scored on story, hook, audio, chat reaction and traction, out of 10.${top.breakdown.traction_label?' '+esc(top.breakdown.traction_label)+'.':''}</p></div></div></section>`}
function approvalFlow(){const steps=[['Scored','The engine scores every moment.','Live'],['Queued','Top clips are queued at 2 a day per channel.','Live'],['Label approval','Optional: the label approves clips before they go out.','Optional'],['Published','Posts go out on the fan pages and the link is recorded.','Live']];return `<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>How a clip goes out</h2><p>Approval is optional. Right now clips post automatically.</p></div></div><div class="flow-steps">${steps.map(([n,d,s],i)=>`<div class="flow-step"><span class="eyebrow muted">0${i+1}</span><h3>${n}</h3><p class="muted small">${d}</p><span class="badge ${s==='Live'?'':'purple'}">${s}</span></div>`).join('')}</div></section>`}
function candidates(){const all=liveForRalfy()&&Array.isArray(live.clips)?live.clips:[];if(!all.length)return '';const rows=all.slice(0,12);return `<div class="split" style="margin-bottom:10px;flex-wrap:wrap;gap:8px"><span class="eyebrow muted">LIVE CANDIDATES ${liveTag}</span><span class="muted small">Top-scored clips from Ralfy’s streams, queued to post automatically. Labels can add an approval step.</span></div><div class="content-grid" style="margin-bottom:22px">${rows.map(c=>`<article class="panel clip"><div class="clip-art"><img src="${esc(c.thumb||'assets/ralfy.png')}" alt="${esc(c.title)}" loading="lazy"><div class="caption">${esc(c.hook||c.title)}</div>${fmtDur(c.duration_s)?`<span class="duration">${esc(fmtDur(c.duration_s))}</span>`:''}</div><div class="split"><span class="badge ${c.status==='Rendered'?'':'gray'}">${esc(c.status==='Rendered'?'Clip ready':'Scored')}</span><span class="small green">${c.viral==null?'':esc(c.viral)+' / 10'}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.kind==='music'?'Music video':'Stream')}${fmtDur(c.duration_s)?` · ${esc(fmtDur(c.duration_s))}`:''}</p><div class="split"><span class="muted small">${esc(c.source_label||'Public source')}</span>${extLink(c.watch_url,'Source')}</div></article>`).join('')}</div>${all.length>rows.length?`<p class="muted small" style="margin:-8px 0 22px">Showing the top ${rows.length} of ${all.length} scored moments.</p>`:''}`}
function sourcesNote(){const seen=new Map();(live&&live.clips||[]).forEach(c=>{if(!c.watch_url)return;const k=c.watch_url+'|'+c.kind;if(!seen.has(k))seen.set(k,c)});const rows=[...seen.values()];return `<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Sources</h2><p>We add sources for you: new streams, music videos and approved footage.</p></div></div>${rows.map((c,i)=>`<div class="settings-row"><div class="connection-logo">${ic(c.kind==='music'?'headphones':'play')}</div><div class="info"><h3>${c.kind==='music'?'Official music video':'Stream'} ${i+1}</h3><p>${esc(c.source_label||'Public source')}</p></div>${extLink(c.watch_url,'Open')}</div>`).join('')}</section>`}
function content(){if(!liveForRalfy())return heading('Content studio','Long streams and music videos, turned into short clips.')+`<div class="note">${sampleMark} Demo roster slot. Clips show here once we onboard the artist and add their sources.</div>`+footer();return heading('Content studio','We turn Ralfy’s long streams and music videos into short clips for the fan pages.')+pipelinePanel()+queueTable()+publishedTable()+scoreCard()+approvalFlow()+candidates()+sourcesNote()+footer()}
function calendar(){if(!liveForRalfy())return heading('Publishing calendar','What goes out, and when.')+`<div class="note">${sampleMark} Demo roster slot. The calendar fills once we onboard the artist.</div>`+footer();const rows=(live.queue||[]).slice();const byDay={};rows.forEach(r=>{const d=new Date(r.scheduled_at);const k=isNaN(d)?'':d.toLocaleDateString('en-US',{timeZone:'America/New_York',weekday:'short',month:'short',day:'numeric'});(byDay[k]=byDay[k]||[]).push(r)});const accts=(live.fans&&live.fans.accounts)||[];return heading('Publishing calendar','Read-only. What goes out on the fan pages, and when.')+`<div class="note">${liveTag} Times are ET. ${accts.map(a=>`${esc(a.platform)} ${a.url?esc((a.slot_times_et||[]).map(t=>{const [h,m]=t.split(':').map(Number);return new Date(2000,0,1,h,m).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}).join(' and ')):'planned'}`).join(' · ')}. 2 posts a day per live channel during warm-up.</div>`+`<div class="calendar-list">${Object.entries(byDay).map(([day,items])=>`<div class="calendar-day"><div class="day-label">${esc(day.split(',')[0])}<b>${esc((day.split(' ').pop())||'')}</b></div><article class="panel"><h3 style="margin-bottom:10px">${esc(day)}</h3>${items.map(r=>`<div class="settings-row"><div class="connection-logo">${esc(chanName(r.platform).slice(0,1))}</div><div class="info"><h3>${esc((r.scheduled_label||'').split(', ').pop())} · ${esc(chanName(r.platform))} ${kindTag(r.kind)}</h3><p>${esc(r.title||'')}</p></div>${postLinkFor(r)}</div>`).join('')}</article></div>`).join('')}</div>`+footer()}
function opportunities(){const s=liveForRalfy()&&live.sponsors?live.sponsors:null;const pr=opTab==='PR & press';const tabsHtml=`<div class="tabs" role="group" aria-label="Opportunity category">${['Brands & partnerships','PR & press'].map(t=>`<button class="tab ${opTab===t?'active':''}" data-optab="${esc(t)}" aria-pressed="${opTab===t}">${t}</button>`).join('')}</div>`;const head=heading('Opportunity engine','We research, pitch and follow up with brands and press. You see the progress.');if(!s)return head+`<div class="note">${sampleMark} Demo roster slot. Outreach starts once we onboard the artist.</div>`+footer();const ch=Array.isArray(s.by_channel)?s.by_channel:[];const em=ch.find(c=>c.channel==='email')||{},fm=ch.find(c=>c.channel==='form')||{};const body=pr?`<section class="panel"><div class="panel-head"><div><h2>PR, press and podcasts</h2><p>Starts once the story and the facts are confirmed with the team.</p></div>${plannedTag}</div>${metrics([['Pitches sent','0','Not started','target','asof'],['Scheduled','0','Not started','calendar','asof'],['Replies','0','Not started','people','asof'],['Features','0','Not started','spark','asof']])}</section>`:metrics([['Emails sent',String(s.sent),`Running total · up to ${s.email_daily_cap||3} a weekday`,'target','asof'],['Emails queued',String(s.queued),'Running total waiting to send, not per day','flag','asof'],['Forms waiting',String(s.forms_queued||0),'Brand contact forms still to fill','grid','asof'],['Forms submitted',String(s.forms_submitted||0),`${s.forms_submitted_today||0} today · up to ${s.forms_daily_cap||10} a day`,'link','asof']])+`<section class="panel"><div class="panel-head"><div><h2>Pipeline ${liveTag}</h2><p>Read-only. Counts by stage; brand names stay private.</p></div></div><div class="table-wrap"><table><thead><tr><th>Stage</th><th>By email</th><th>By contact form</th><th>Total</th></tr></thead><tbody>${[['Sent',em.sent||0,fm.submitted||0],['Scheduled',em.queued||0,fm.queued||0],['Replied',em.replies||0,0],['Watching',s.watchlist||0,0]].map(([n,a,b])=>`<tr><td>${n}</td><td>${a}</td><td>${b}</td><td><b>${a+b}</b></td></tr>`).join('')}</tbody></table></div><p class="muted small" style="margin-top:12px">Excluded categories and anything on legal review are left out. Every pitch is checked before it goes.</p></section>`;return head+`<div class="note">${liveTag} Counts only. Brand names, contacts and deal terms stay off this page.</div>`+tabsHtml+body+footer()}
function fans(){if(!liveForRalfy())return heading('Fans & community','Where the audience lives, and how we reach it again.')+`<div class="note">${sampleMark} Demo roster slot.</div>`+metrics([['Owned fans','284','Sample','people','sample'],['Email opt-ins','210','Sample','link','sample']])+footer();const f=live.fans||{};const ig=(live.highlights||[]).find(h=>/instagram/i.test(h.label));return heading('Fans & community','Where Ralfy’s audience lives today, and what we build once the lists are connected.')+officialKpis()+fanPanel()+`<section class="panel"><div class="panel-head"><div><h2>Planned once connected</h2><p>With the email/SMS list and Shopify customers connected, we can measure business outcomes.</p></div>${plannedTag}</div>${[['Email and SMS list','Reach fans directly on release and drop days, without relying on the algorithm.'],['Shopify customers','See repeat buyers and give them first access to drops.'],['Outcomes we report','Release-day reach, drop sell-through, repeat-buyer rate and revenue per fan.']].map(([n,d])=>`<div class="segment"><div class="task-icon">${ic('people')}</div><div><h3>${n}</h3><p>${d}</p></div><span class="badge gray" style="margin-left:auto">Not connected</span></div>`).join('')}</section>`+footer()}
function emailCards(){const c=live&&live.commerce;if(!c)return '';const pages=(c.email_pages||[]);const byId=Object.fromEntries(pages.map(p=>[p.id,p]));const list=(c.emails||[]).filter(e=>byId[e.id]).sort((a,b)=>((byId[b.id]||{}).featured?1:0)-((byId[a.id]||{}).featured?1:0));return `<section class="panel" style="margin-top:22px"><div class="panel-head"><div><h2>Designed merch emails ${liveTag}</h2><p>${c.emails_built||list.length} emails built. Open any design below. Nothing sends until the fan list is connected. Drop emails stay off this public page until approved.</p></div></div><div class="cards">${list.map(e=>{const pg=byId[e.id];return `<article class="panel campaign-card">${pg&&pg.featured?'<span class="badge purple">Featured</span>':'<span class="badge gray">Ready</span>'}<h2>${esc(e.subject)}</h2><p>${esc(e.series||'')}</p>${e.preheader?`<p class="muted small">${esc(e.preheader)}</p>`:''}${pg?`<a class="btn" href="${esc(pg.html)}" target="_blank" rel="noopener">View email ${ic('arrow')}</a>`:''}</article>`}).join('')}</div></section>`}
function commerce(){const real=liveForRalfy()&&live.commerce;return heading('Commerce','The official store, the drops we plan, and the emails that sell them.')+`<section class="panel merch-feature">${(()=>{const f=real&&(live.commerce.products||[]).find(p=>p.available&&p.image&&/plug walk/i.test(p.title));return f?`<img src="${esc(f.image)}&width=900" alt="${esc(f.title)} from the official STINC TEAM store">`:'<img src="assets/ralfy.png" alt="Ralfy the Plug">'})()}<div class="merch-info"><span class="eyebrow green">OFFICIAL STORE / PRODUCT SPOTLIGHT</span><h2>Built for the team.</h2><p>We tie merch into the content: clips point fans to the store, and designed emails carry each drop.</p><div class="actions"><a class="btn" href="https://stincteamtgf.com/" target="_blank" rel="noopener noreferrer">Visit official store ↗</a><a class="btn primary" href="store-concept/" target="_blank" rel="noopener">See our store rebuild ↗</a><span class="badge purple">Concept</span></div></div></section><br>`+commerceMetrics()+commerceNote()+(real?commerceRack()+emailCards():'')+footer()}
function commerceRack(){const c=live.commerce;const products=(c.products||[]).map(p=>`<tr><td>${esc(p.title)}<small>${esc(p.category||'')}${p.instock_sizes&&p.instock_sizes.length?' · '+esc(p.instock_sizes.join(', ')):''}</small></td><td>${esc(money(p.price_min))}</td><td><span class="badge ${p.available?'':'gray'}">${p.available?'In stock':'Sold out'}</span></td><td>${extLink(p.url,'View')}</td></tr>`).join('');return `<section class="panel"><div class="panel-head"><div><h2>Public rack ${liveTag}</h2><p>${esc(String(c.shown_count||0))} shown of ${esc(String(c.store_published_count||''))} on the store</p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th></th></tr></thead><tbody>${products}</tbody></table></div></section>`}
function revenue(){return heading('Revenue','A view across the artist business, with the gaps visible.')+`<div class="note">${sampleMark} Sample figures. No distributor, royalty, publishing or bank account is connected yet, so these are not actual earnings.</div>`+metrics([['Reported','$18,720','Sample','money','sample'],['Estimated','$4,860','Sample','headphones','sample'],['Awaiting review','$2,140','Sample','calendar','sample'],['Revenue sources','4','Sample','link','sample']])+`<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Revenue ledger ${sampleMark}</h2><p>Sample reporting period · USD</p></div></div><div class="table-wrap"><table><thead><tr><th>Source</th><th>Amount</th><th>Record type</th><th>What happens next</th></tr></thead><tbody>${[['Merchandise','$12,480','Reported','Reconcile with Shopify orders'],['Distribution','$6,240','Reported','Match distributor statement'],['Streaming forecast','$4,860','Estimated','Await final statement'],['Publishing','$2,140','Awaiting review','Confirm registrations and reporting period']].map(([s,a,t,n])=>`<tr><td>${s}<small>Sample record</small></td><td>${a}</td><td><span class="badge ${t==='Reported'?'':t==='Estimated'?'purple':'yellow'}">${t}</span></td><td>${n}</td></tr>`).join('')}</tbody></table></div></section>`+needsPanel('Connect for the full picture','Give us access to these and this page shows real revenue.')+footer()}
function integrations(){const groups=['Streaming','Commerce','Social','Clipping'];return heading('Connections','We connect each account for you, with admin or collaborator access.')+needsPanel('What we need from you / next steps','Access to these accounts, in this order of value. No passwords.')+groups.map(group=>`<section class="panel" style="margin-bottom:18px"><div class="panel-head"><h2>${group}</h2></div>${CONNECTORS.filter(c=>c.group===group).map(c=>`<div class="settings-row"><div class="connection-logo">${c.mark}</div><div class="info"><h3>${c.name}</h3><p>${c.blurb}</p></div>${connectorBadge(c)}</div>`).join('')}</section>`).join('')+footer()}
function workforce(){const procs=(OPS()&&OPS().processes)||[];const hb=(h)=>h==='Healthy'?'<span class="badge">Healthy</span>':h==='Scheduled'?'<span class="badge purple">Scheduled</span>':`<span class="badge yellow">${esc(h)}</span>`;if(!liveForRalfy())return heading('Agent workforce','The processes we run for each artist.')+`<div class="note">${sampleMark} Demo roster slot. Processes start once we onboard the artist.</div>`+footer();return heading('Agent workforce','The processes running for Ralfy right now. Read-only.')+refreshNote()+`<div class="cards">${procs.map(p=>`<article class="panel agent-card"><div class="split"><div class="agent-orb">${ic('spark')}</div>${hb(p.health)}</div><h2>${esc(p.name)}</h2><p>${esc(p.what)}</p><div class="proc-meta"><span><b>Schedule</b>${esc(p.cadence)}</span><span><b>Last run</b>${esc(p.last_run||'—')}</span><span><b>Next run</b>${esc(p.next_run||'—')}</span></div>${p.note?`<p class="muted small" style="margin-top:10px">${esc(p.note)}</p>`:''}</article>`).join('')}</div><br>`+(Array.isArray(live.activity)&&live.activity.length?`<section class="panel"><div class="panel-head"><div><h2>Execution history ${liveTag}</h2><p>From the system logs.</p></div></div>${live.activity.slice(0,12).map(a=>`<div class="activity"><span class="activity-dot"></span><div><b>${esc(a.label)}</b><p>${esc(a.detail||'')} · ${fmtWhen(a)}</p></div></div>`).join('')}</section>`:'')+footer()}
function roster(){const f=live&&live.fans||{},p=live&&live.pipeline||{};return heading('Artist roster','One workspace per artist, with label-wide visibility.')+`<div class="calendar-list">${[['ralfy','Ralfy the Plug','Featured artist · STINC TEAM',live?`${f.channels_live||0} fan channels live · ${p.clips_rendered||0} clips rendered`:''],['roster','Emerging artist','Demo roster slot · not a real artist','Sample workspace']].map(([id,n,d,m])=>`<article class="panel roster-card">${id==='ralfy'?'<img src="assets/ralfy.png" alt="Ralfy the Plug">':'<div class="roster-avatar">EA</div>'}<div><span class="eyebrow muted">${id==='ralfy'?'ARTIST SPOTLIGHT':'DEMO ROSTER SLOT'}</span><h2>${n}</h2><p class="muted small">${d}</p>${m?`<p class="small green" style="margin-top:8px">${esc(m)}</p>`:''}</div>${button('Open workspace',`artist:${id}`,id===state.artist,'arrow')}</article>`).join('')}<article class="panel roster-card"><div class="roster-avatar">${ic('plus')}</div><div><span class="eyebrow muted">NEXT ARTIST</span><h2>We onboard new artists</h2><p class="muted small">Tell us who is next. We set up their sources, fan pages and outreach, then their workspace appears here.</p></div></article></div>`+footer()}
function renderPage(){const views={overview,operations,content,calendar,opportunities,fans,commerce,revenue,agents:workforce,roster,integrations};return (views[page]||overview)()}
function empty(t,d,b,a){return `<div class="empty"><h2>${t}</h2><p>${d}</p>${button(b,a,true,'plus')}</div>`}
function fmtDate(d){return new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}
function toast(msg){let el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500)}
function navigate(p){if(location.hash==='#'+p){page=p;shell()}else location.hash=p}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;shell()}));document.querySelectorAll('[data-optab]').forEach(b=>b.addEventListener('click',()=>{opTab=b.dataset.optab;shell()}));document.getElementById('artist-select').addEventListener('change',e=>{state.artist=e.target.value;save();filter='All';shell()});document.getElementById('period')?.addEventListener('change',e=>{period=e.target.value;shell()})}
function modal(title,body,wide=false){lastFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${ic('close')}</button></header><div class="modal-content">${body}</div></section></div>`;document.body.style.overflow='hidden';document.querySelectorAll('#overlay [data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));document.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});document.querySelector('.modal input,.modal select,.modal textarea,.modal button')?.focus()}
function closeModal(){document.getElementById('overlay').innerHTML='';document.body.style.overflow='';lastFocus?.isConnected&&lastFocus.focus()}
const field=(label,name,value='',type='text',hint='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" required ${type==='date'?'min="2026-11-07"':''}>${hint?`<span class="hint">${hint}</span>`:''}</label>`;
function newCampaign(type='Release rollout'){modal('Make the next move.',`<p>Start with the goal. Build a connected plan around it.</p><form id="campaign-form">${field('Campaign name','name','','text')}<div class="form-grid"><label class="field">Campaign type<select name="type">${['Release rollout','Livestream growth','Merchandise drop','Brand partnerships','PR campaign','Always-on growth'].map(t=>`<option ${t===type?'selected':''}>${t}</option>`).join('')}</select></label>${field('Target date','date','2026-11-20','date')}</div><label class="field">What are we working toward?<textarea name="goal" required placeholder="Grow the next release through livestreams, daily clips and a fan early-access list."></textarea></label><div class="note">This creates a saved campaign plan for ${esc(artistName())}. You can review the rollout before activation.</div><div class="modal-footer">${button('Cancel','close')}<button class="btn primary" type="submit">Build campaign ${ic('arrow')}</button></div></form>`);document.getElementById('campaign-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const c={id:'c'+Date.now(),artist:state.artist,name:f.get('name').trim(),type:f.get('type'),date:f.get('date'),goal:f.get('goal').trim(),status:'Draft',progress:0};if(!c.name||!c.goal)return;state.campaigns.unshift(c);log('Campaign strategist built “'+c.name+'”','A coordinated draft is ready for manager review.');closeModal();page='campaigns';filter='All';if(location.hash==='#campaigns'){shell();campaignDetail(c.id)}else{pendingCampaign=c.id;navigate('campaigns')}})}
const campaignPlans={
'Release rollout':[['Set the release story','Confirm the release assets, audience, DSP destination and one primary streaming goal.'],['Build the anticipation','Plan a studio livestream, three teaser clips and a consent-based early-access fan list.'],['Coordinate release day','Align the music link, release-day posts, community announcement and merchandise spotlight.'],['Extend the momentum','Review the first-week response, repurpose standout moments and plan the follow-up content.']],
'Livestream growth':[['Give the session a purpose','Choose the platform, format and fan action; set a live audience and watch-time target.'],['Bring fans into the room','Plan the announcement, reminder clips and opt-in livestream notification.'],['Make the live moment count','Outline the opening hook, audience interaction and approved sponsor or merchandise moments.'],['Turn live into lasting reach','Review the recording for clips, schedule platform-specific posts and invite viewers back.']],
'Merchandise drop':[['Build the drop','Confirm product, inventory, pricing, store destination and sales target with the team.'],['Give insiders the first look','Plan the product reveal, early-access fan segment and creative assets.'],['Launch across the ecosystem','Coordinate the store release, livestream mention and approved launch posts.'],['Learn and bring fans back','Review sales and conversion, follow up with consented fans and reconcile store orders.']],
'Brand partnerships':[['Define the offer','Set the audience story, available deliverables, partner categories and target deal size.'],['Qualify the right partners','Research public brand information, document fit and verify business contact sources.'],['Prepare the conversation','Build a tailored pitch and evidence-backed offer for manager review.'],['Manage the relationship','Track approved follow-ups, negotiate scope and record deliverables and outcomes.']],
'PR campaign':[['Find the story','Define the editorial angle, release context and verified facts for the press kit.'],['Build the media list','Research relevant publications, podcasts and publicly listed editorial contacts.'],['Pitch with a purpose','Prepare a short, tailored story proposal and manager-approved press assets.'],['Coordinate the coverage','Track responses, interview preparation, approved follow-ups and published links.']],
'Always-on growth':[['Choose the growth focus','Set a measurable audience or business goal and document the current baseline.'],['Build the weekly rhythm','Plan long-form sessions, daily short-form moments and a recurring fan invitation.'],['Connect the business','Coordinate community, commerce and relevant commercial opportunities.'],['Review and improve','Compare performance with the baseline and adjust next week’s plan.']]};
function campaignDetail(id){let c=state.campaigns.find(c=>c.id===id);if(!c)return;modal(esc(c.name),`<div class="split" style="margin-bottom:18px"><span class="badge ${c.status==='Draft'?'gray':''}">${esc(c.status)}</span><span class="muted small">${esc(c.type)} · ${fmtDate(c.date)}</span></div><p>${esc(c.goal)}</p>${(campaignPlans[c.type]||campaignPlans['Always-on growth']).map(([t,d],i)=>`<div class="step"><div class="step-number">${i+1}</div><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}<div class="note">Activation updates your demo plan. External posting, outreach and DSP actions require authorized integrations.</div><div class="modal-footer">${button('Open content','campaign-content')} ${c.status==='Draft'?button('Activate demo plan',`activate:${id}`,true,'check'):c.status==='Active'?button('Mark complete',`complete:${id}`,true,'check'):button('Close','close')}</div>`)}
function clipDetail(id){let c=state.clips.find(c=>c.id===id);if(!c)return;modal('Review the moment.',`<p>${esc(c.title)} · Storyboard and publishing plan</p><div class="note">Sample visual storyboard. No playable source video is attached. Candidate: ${esc(c.start)} · ${esc(c.duration)} · Fit score ${c.score}/100.</div><form id="clip-form"><label class="field">On-screen hook<input name="hook" value="${esc(c.hook)}" required maxlength="100"></label><label class="field">Caption<textarea name="caption" required>${esc(c.caption)}</textarea></label><label class="field">Destination<select name="platform">${['YouTube Shorts','Instagram Reels','TikTok','Facebook Reels'].map(t=>`<option ${c.platform===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="form-grid">${field('Publish date (PT)','date',c.date,'date')}${field('Publish time (PT)','time',c.time,'time')}</div><div class="modal-footer">${c.status==='Scheduled'?button('Move to review',`unschedule:${id}`):button('Cancel','close')}<button class="btn primary" type="submit">Save to demo calendar ${ic('calendar')}</button></div></form>`);document.getElementById('clip-form').addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);Object.assign(c,{hook:f.get('hook').trim(),caption:f.get('caption').trim(),platform:f.get('platform'),date:f.get('date'),time:f.get('time'),status:'Scheduled'});log('Content scheduled: '+c.title,c.platform+' · '+fmtDate(c.date)+' · '+c.time+' PT · Demo plan only');closeModal();shell();toast('Saved to your demo calendar. No live post was sent.')})}
function addSource(){modal('One source. More possibilities.',`<p>Add a source reference to create three sample clip candidates for review.</p><form id="source-form">${field('Source title','title','','text')}<label class="field">Source URL<input name="url" type="url" placeholder="https://www.youtube.com/watch?v=…" required><span class="hint">A reference only. This demo does not fetch or process the video.</span></label><label class="field">Source type<select name="type"><option>YouTube video</option><option>Twitch livestream</option><option>Kick livestream</option><option>Studio session</option></select></label><div class="modal-footer">${button('Cancel','close')}<button type="submit" class="btn primary">Create sample candidates ${ic('spark')}</button></div></form>`);document.getElementById('source-form').addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),title=f.get('title').trim();if(!title)return;let url=new URL(f.get('url'));if(!['https:','http:'].includes(url.protocol)){toast('Use an https:// or http:// source URL.');return}['The opening hook','The story worth sharing','The community moment'].forEach((t,i)=>state.clips.push({id:'v'+Date.now()+i,artist:state.artist,title:t,caption:'Tap in for the next chapter. Follow '+artistName()+' for more.',hook:t,duration:['0:24','0:32','0:41'][i],score:92-i*3,platform:['YouTube Shorts','Instagram Reels','TikTok'][i],status:'Needs review',date:'2026-11-12',time:'18:00',source:title+' · sample candidate',start:['00:20','02:14','05:08'][i],url:url.href}));log('Content producer prepared 3 sample candidates',title+' · Source reference saved; video processing not connected.');closeModal();filter='All';navigate('content');shell();toast('Three sample storyboards are ready for review.')})}
function leadDetail(id){let o=state.leads.find(x=>x.id===id);modal('A conversation worth starting.',`<span class="badge purple" style="margin-bottom:18px">${esc(o.type)} · ${o.score}/100 sample fit</span><h3 style="margin-bottom:10px">${esc(o.name)}</h3><p>${esc(o.reason)}</p><div class="detail-list"><div><span>Potential / format</span><b>${esc(o.value)}</b></div><div><span>Contact status</span><b>${esc(o.contact)}</b></div><div><span>Pipeline stage</span><b>${esc(o.stage)}</b></div></div><br><label class="field">Pitch draft<textarea id="pitch" style="min-height:150px">${esc(state.pitches[id]||`Hi [name],\n\nI’m reaching out on behalf of ${artistName()} and STINC TEAM. We’re exploring ${o.type==='PR & press'?'a conversation around independent music, creative process and community':'a focused partnership around music, livestream content and fan culture'}.\n\n${o.reason}\n\nWould you be open to a short conversation about the fit?\n\n[Manager name]`)}</textarea><span class="hint">Template only. Verify the recipient, artist facts, offer and permissions before sending.</span></label><div class="modal-footer">${button('Save pitch draft',`save-pitch:${id}`,true,'check')}${button('Move to manager review',`ready-lead:${id}`)}</div>`)}
function fanForm(){modal('Build a fan-capture moment.',`<p>Create a saved page brief for the next release, livestream or drop. Live fan collection requires a CRM connection.</p><form id="fan-form">${field('Page headline','headline',state.fanPages[state.artist]?.headline||'Be first for the next chapter.')}<label class="field">Offer<select name="offer">${['Early music access','Livestream reminder','Merchandise early access'].map(t=>`<option ${state.fanPages[state.artist]?.offer===t?'selected':''}>${t}</option>`).join('')}</select></label>${field('Call to action','cta',state.fanPages[state.artist]?.cta||'Join the inner circle')}<label class="check"><input type="checkbox" required>Include explicit email opt-in and an unsubscribe option.</label><div class="modal-footer">${button('Cancel','close')}<button type="submit" class="btn primary">Save page brief ${ic('check')}</button></div></form>`);document.getElementById('fan-form').addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);state.fanPages[state.artist]=Object.fromEntries(f);log('Community operator saved a fan-capture brief',f.get('headline')+' · '+f.get('offer'));closeModal();shell();toast('Fan-capture brief saved. Live collection is not connected.')})}
function newLead(){modal('Add an opportunity.',`<form id="lead-form">${field('Brand or publication','name')}<label class="field">Pipeline<select name="type"><option>Brands & partnerships</option><option>PR & press</option></select></label>${field('Category / angle','category')}<label class="field">Why does this fit?<textarea name="reason" required></textarea></label><div class="modal-footer">${button('Cancel','close')}<button class="btn primary" type="submit">Save opportunity</button></div></form>`);document.getElementById('lead-form').addEventListener('submit',e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));state.leads.push({...f,artist:state.artist,id:'o'+Date.now(),score:0,stage:'Research needed',value:'To be scoped',contact:'Public contact verification required'});opTab=f.type;log('Opportunity added: '+f.name,'Research and qualification required.');closeModal();shell();toast('Opportunity saved for research.')})}
function settings(){modal('You set the boundaries.',`<p>Demo execution preferences are saved in this browser. Live actions remain unavailable until connected.</p><form id="settings-form"><label class="check"><input type="checkbox" name="review" ${state.settings.review?'checked':''}>Require manager review in campaign plans</label><label class="check"><input type="checkbox" name="weekly" ${state.settings.weekly?'checked':''}>Include a weekly performance review in plans</label><div class="note">Live publishing: disabled<br>Live outreach: disabled<br>Payments and purchases: disabled</div><div class="modal-footer">${button('Export workspace','export')}<button class="btn primary" type="submit">Save preferences</button></div></form>`);document.getElementById('settings-form').addEventListener('submit',e=>{e.preventDefault();state.settings={review:e.target.review.checked,weekly:e.target.weekly.checked};save();closeModal();toast('Workspace preferences saved.')})}
function download(){let data={...state,exportedAt:new Date().toISOString(),notice:'STINC OS concept demo. Sample records; not actual artist analytics or financial data.'};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='stinc-os-demo-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo workspace exported as JSON.')}
function action(a){const [act,...parts]=a.split(':'),id=parts.join(':');if(act==='close')return closeModal();if(act==='menu'){let side=document.getElementById('sidebar');let open=side.classList.toggle('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded',String(open));if(open)document.querySelector('.mobile-close').focus();else document.querySelector('.mobile-menu').focus();return}if(act.startsWith('go-'))return navigate(act.slice(3));switch(act){case 'new-campaign':return newCampaign();case 'merch-plan':return newCampaign('Merchandise drop');case 'campaign':return campaignDetail(id);case 'campaign-content':closeModal();return navigate('content');case 'activate':case 'complete':{let c=state.campaigns.find(x=>x.id===id);c.status=act==='activate'?'Active':'Completed';c.progress=act==='activate'?10:100;log('Campaign '+(act==='activate'?'activated':'completed')+': '+c.name,'Demo plan updated; no external actions performed.');closeModal();shell();return toast('Campaign '+c.status.toLowerCase()+'.')}case 'clip':return clipDetail(id);case 'add-source':return addSource();case 'unschedule':{state.clips.find(x=>x.id===id).status='Needs review';save();closeModal();shell();return toast('Moved back to the review queue.')}case 'lead':return leadDetail(id);case 'new-lead':return newLead();case 'save-pitch':state.pitches[id]=document.getElementById('pitch').value;state.leads.find(x=>x.id===id).stage='Draft ready';log('Pitch draft saved','No message sent. Verify recipient and offer before live outreach.');closeModal();shell();return toast('Pitch saved. No outreach was sent.');case 'ready-lead':state.pitches[id]=document.getElementById('pitch').value;state.leads.find(x=>x.id===id).stage='Ready for review';log('Opportunity moved to manager review','Contact verification and approval required before outreach.');closeModal();shell();return toast('Saved for manager review. No outreach was sent.');case 'fan-form':return fanForm();case 'settings':return settings();case 'export':return download();case 'artist':state.artist=id;save();closeModal();return navigate('overview');case 'toggle-agent':state.paused=state.paused.includes(id)?state.paused.filter(x=>x!==id):[...state.paused,id];save();shell();return;case 'run-agent':{if(state.paused.includes(id))return;let title=agents.find(x=>x[0]===id)[1];if(id==='campaign')return newCampaign();if(id==='content')return addSource();if(id==='community')return fanForm();log(title+' refreshed the opportunity review','Two sample brand opportunities ranked; public contact research still required.');shell();return toast('Sample opportunity review added to execution history.')}case 'connect':return connectModal(id);case 'save-store':{const input=document.getElementById('store-url');const value=(input&&input.value||'').trim();if(value&&!/^https:\/\//i.test(value)){toast('Use an https:// store URL.');return}state.storeUrl=value;save();closeModal();shell();return toast(value?'Store URL saved in this browser. The site was not fetched.':'Store URL cleared.');}case 'notifications':return modal('Your team, in motion.',state.activity.slice(0,8).map(x=>`<div class="step"><span class="activity-dot"></span><div><h3>${esc(x.title)}</h3><p>${esc(x.detail)} · ${esc(x.at)}</p></div></div>`).join('')+`<div class="modal-footer">${button('Close','close')}</div>`);case 'tour':return modal('From attention to a business.',`<p>Three connected journeys to explore with EVOL and the team.</p>${[['Build the next rollout','Create a campaign, review the coordinated plan and activate it in the demo.'],['Make every session work harder','Add a video reference, create sample clip candidates and save posts to the calendar.'],['Open a new revenue lane','Review a brand or press opportunity, refine a pitch and move it into manager review.']].map(([t,d],i)=>`<div class="step"><div class="step-number">${i+1}</div><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}<div class="modal-footer">${button('Start a campaign','new-campaign',true,'arrow')}</div>`);case 'about':return modal('An operating system for independence.',`<p>STINC OS is a presentation concept prepared for a discussion with EVOL / STINC TEAM. It is not an official STINC TEAM product or endorsement.</p><ul class="help-list"><li><b>Working in this demo:</b> campaigns, clip storyboards, demo scheduling, pitch drafts, roster switching, fan-capture briefs, agent controls and JSON export.</li><li><b>Saved in your browser:</b> changes persist on this device using local storage. There is no shared database or sign-in.</li><li><b>Public snapshot:</b> audience counts, the fan-page network and upcoming queue, the content pipeline, sponsor and form totals (counts only), activity, the merch catalog, and clip candidates load from data/live.json when that file is present.</li><li><b>Sample:</b> rows marked Sample, including campaign plans, the chart, owned-fan totals, finance, and demo storyboards. Live activity replaces the sample agent list when the snapshot is present. This public site does not send posts or messages itself.</li><li><b>Official public imagery:</b> artist portrait and merchandise from <a href="https://stincteamtgf.com/" target="_blank" rel="noopener noreferrer" class="green">stincteamtgf.com ↗</a>.</li><li><b>Next phase:</b> authenticated workspaces, server-side orchestration, authorized integrations and a real pilot campaign.</li></ul><div class="modal-footer">${button('Explore the demo','close',true)}</div>`);}}
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){document.getElementById('main').focus();return}page=location.hash.slice(1)||'overview';filter='All';closeModal();shell();window.scrollTo(0,0);if(pendingCampaign){let id=pendingCampaign;pendingCampaign=null;campaignDetail(id)}});
document.addEventListener('keydown',e=>{if(!document.querySelector('.modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...document.querySelectorAll('.modal button,.modal input,.modal textarea,.modal select,.modal a')].filter(x=>!x.disabled);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function boot(){const finish=()=>shell();if(typeof fetch!=='function'){finish();return}fetch('data/live.json',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(d=>{if(d&&d.schema==='stinc-os.live.v1')live=d}).catch(()=>{}).finally(finish)}
boot();
